  mutate: vi.fn(),
  mutateAsync: vi.fn().mockResolvedValue(undefined),
  data: undefined,
  error: null,
  isPending: false,
  isIdle: true,
  isSuccess: false,
  isError: false,
  variables: undefined,
  context: undefined,
  failureCount: 0,
  failureReason: null,
  isPaused: false,
  status: 'idle' as const,
  submittedAt: 0,
  reset: vi.fn(),
} satisfies UseMutationResult<AcceptInviteResponse, AcceptInviteError, string>

const authenticatedUser = {
  user: undefined,
  isLoading: false,
  isUnauthenticated: false,
  isNotRegistered: true,
  isError: true,
}

function renderPage(token = 'testtoken123') {
  const { Wrapper } = createQueryClientWrapper()

  function RouterWrapper({ children }: { children: ReactNode }) {
    return (
      <Wrapper>
        <MemoryRouter initialEntries={[`/accept/${token}`]}>{children}</MemoryRouter>
      </Wrapper>
    )
  }

  return render(
    <Routes>
      <Route path="/accept/:token" element={<AcceptInvitePage />} />
      <Route path="/" element={<div>Home Page</div>} />
    </Routes>,
    { wrapper: RouterWrapper }
  )
}

beforeEach(() => {
  mockUseCurrentUser.mockReturnValue({
    user: undefined,
    isLoading: false,
    isUnauthenticated: false,
    isNotRegistered: true,
    isError: true,
  })
  mockUseAcceptInvite.mockReturnValue({ ...idleMutation })
})

describe('AcceptInvitePage', () => {
  it('renders a level-1 heading — WCAG AA gate', () => {
    renderPage()
    expect(screen.getByRole('heading', { level: 1 })).toBeInTheDocument()
  })

  it('unauthenticated state renders Accept & Sign in with Google button', () => {
    mockUseCurrentUser.mockReturnValue({
      user: undefined,
      isLoading: false,
      isUnauthenticated: true,
      isNotRegistered: false,
      isError: true,
    })

    renderPage()

    expect(screen.getByRole('link', { name: /accept.*sign in.*google/i })).toBeInTheDocument()
  })

  it('authenticated state auto-calls accept mutation with the token', async () => {
    const mockMutateAsync = vi.fn().mockResolvedValue(undefined)
    mockUseAcceptInvite.mockReturnValue({ ...idleMutation, mutateAsync: mockMutateAsync })
    mockUseCurrentUser.mockReturnValue(authenticatedUser)

    renderPage('myspecialtoken')

    await waitFor(() => {
      expect(mockMutateAsync).toHaveBeenCalledWith('myspecialtoken')
    })
  })

  it('shows no alert in idle state', () => {
    mockUseCurrentUser.mockReturnValue(authenticatedUser)
    renderPage()
    expect(screen.queryByRole('alert')).not.toBeInTheDocument()
  })

  it('410 error renders invitation no longer valid message with alert role', () => {
    mockUseCurrentUser.mockReturnValue(authenticatedUser)
    mockUseAcceptInvite.mockReturnValue({
      ...idleMutation,
      isError: true,
      isIdle: false,
      status: 'error' as const,
      error: { status: 410, code: 'invite.invalid', title: 'This invitation is no longer valid.' },
    })

    renderPage()

    expect(screen.getByRole('alert')).toHaveTextContent(/no longer valid/i)
  })

  it('422 error renders issued to different email message with alert role', () => {
    mockUseCurrentUser.mockReturnValue(authenticatedUser)
    mockUseAcceptInvite.mockReturnValue({
      ...idleMutation,
      isError: true,
      isIdle: false,
      status: 'error' as const,
      error: {
        status: 422,
        code: 'invite.email_mismatch',
        title: 'This invitation was issued to a different email address.',
      },
    })

    renderPage()

    expect(screen.getByRole('alert')).toHaveTextContent(/different email/i)
  })
})

import { render, screen } from '@testing-library/react'
import { describe, it, expect } from 'vitest'
import SignInPage from '../../src/pages/SignInPage'

describe('SignInPage', () => {
  it('renders a level-1 heading — WCAG AA gate', () => {
    render(<SignInPage />)
    expect(screen.getByRole('heading', { level: 1, name: /sign in/i })).toBeInTheDocument()
  })

  it('renders a sign in with Google button', () => {
    render(<SignInPage />)
    expect(screen.getByRole('link', { name: /sign in with google/i })).toBeInTheDocument()
  })

  it('sign-in link points to the auth signin endpoint', () => {
    render(<SignInPage />)
    const link = screen.getByRole('link', { name: /sign in with google/i })
    expect(link).toHaveAttribute('href', '/api/v1/auth/signin')
  })
})

import {
  FluentProvider,
  webLightTheme,
  Button,
  MessageBar,
  MessageBarBody,
  Title1,
  makeStyles,
  tokens,
} from '@fluentui/react-components'
import { useEffect, useRef } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { useCurrentUser } from '../hooks/useCurrentUser'
import { type AcceptInviteError, useAcceptInvite } from '../hooks/useAcceptInvite'

const useStyles = makeStyles({
  root: {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    minHeight: '100vh',
    gap: tokens.spacingVerticalL,
    textAlign: 'center',
    padding: tokens.spacingHorizontalXXL,
  },
})

export default function AcceptInvitePage() {
  const styles = useStyles()
  const { token } = useParams<{ token: string }>()
  const navigate = useNavigate()
  const { isUnauthenticated } = useCurrentUser()
  const { mutateAsync, error } = useAcceptInvite()
  const hasAttempted = useRef(false)

  useEffect(() => {
    if (hasAttempted.current) return
    if (!isUnauthenticated && token) {
      hasAttempted.current = true
      mutateAsync(token).then(() => navigate('/')).catch(() => {})
    }
  }, [isUnauthenticated, token, mutateAsync, navigate])

  const acceptError = error as AcceptInviteError | null

  return (
    <FluentProvider theme={webLightTheme}>
      <div className={styles.root}>
        <Title1 as="h1">Accept Invitation</Title1>

        {isUnauthenticated && (
          <Button
            as="a"
            appearance="primary"
            href={`/api/v1/auth/signin?returnUrl=${encodeURIComponent(`/accept/${token ?? ''}`)}`}
            aria-label="Accept and Sign in with Google"
          >
            Accept &amp; Sign in with Google
          </Button>
        )}

        {acceptError?.status === 410 && (
          <MessageBar intent="error" role="alert">
            <MessageBarBody>
              This invitation is no longer valid. Please request a new one.
            </MessageBarBody>
          </MessageBar>
        )}

        {acceptError?.status === 422 && (
          <MessageBar intent="error" role="alert">
            <MessageBarBody>
              This invitation was issued to a different email address.
            </MessageBarBody>
          </MessageBar>
        )}
      </div>
    </FluentProvider>
  )
}

