13	// Dev-only test infrastructure — architecture boundary exception.
14	// Direct DataAccess and Domain usage is intentional here; this file is
15	// never registered outside IsDevelopment() and must not ship to production.
16	internal static class DevEndpoints
17	{
18	    internal static void Map(IEndpointRouteBuilder routes)
19	    {
20	        routes.MapGet("/dev/authenticate",
21	            async (
22	                string email,
23	                string? displayName,
24	                IUserRepository userRepository,
25	                IOptions<CorsOptions> corsOptions,
26	                HttpContext ctx) =>
27	            {
28	                var user = await userRepository.FindByEmailAsync(email);
29	
30	                List<Claim> claims;
31	                if (user is not null)
32	                {
33	                    claims =
34	                    [
35	                        new Claim("sub", user.GoogleSub ?? $"dev-sub-{email}"),
36	                        new Claim("email", user.Email),
37	                        new Claim("name", user.DisplayName),
38	                        new Claim("user_id", user.Id.ToString()),
39	                        new Claim("system_role",
40	                            user.SystemRole == SystemRole.Admin ? "admin" : "standard"),
41	                    ];
42	                }
43	                else
44	                {
45	                    claims =
46	                    [
47	                        new Claim("sub", $"dev-sub-{email}"),
48	                        new Claim("email", email),
49	                        new Claim("name", displayName ?? email),
50	                    ];
51	                }
52	
53	                var identity = new ClaimsIdentity(
54	                    claims, CookieAuthenticationDefaults.AuthenticationScheme);
55	                await ctx.SignInAsync(
56	                    CookieAuthenticationDefaults.AuthenticationScheme,
57	                    new ClaimsPrincipal(identity));
58	
59	                var frontendOrigin = corsOptions.Value.AllowedOrigins.FirstOrDefault()
60	                    ?? "http://localhost:5173";
61	                return Results.Redirect(frontendOrigin);
62	            })
63	            .WithName("DevAuthenticate")
64	            .WithSummary("[DEV ONLY] Issue an auth cookie without Google OAuth — Playwright use only")
65	            .AllowAnonymous();
66	
67	        routes.MapPost("/dev/seed/invitation",
68	            async (
69	                DevSeedInvitationRequest request,
70	                IDbConnection db) =>
71	            {
72	                var adminId = await db.QuerySingleOrDefaultAsync<string>(
73	                    "SELECT id FROM users WHERE system_role = 'Admin' LIMIT 1");
74	
75	                if (adminId is null)
76	                    return Results.NotFound("No admin user found in database");
77	
78	                var (rawToken, tokenHash) = GenerateToken();
79	                var now = DateTimeOffset.UtcNow;
80	                var expiresAt = now.AddDays(request.ExpiresInDays ?? 7);
81	                var consumedAt = request.Consumed ? now.AddMinutes(-1) : (DateTimeOffset?)null;
82	
83	                await db.ExecuteAsync(
84	                    """
85	                    INSERT INTO invitations
86	                        (id, email, issued_by_user_id, token_hash, issued_at, expires_at, consumed_at, consumed_by_user_id)
87	                    VALUES (@id, @email, @issuedByUserId, @tokenHash, @issuedAt, @expiresAt, @consumedAt, NULL)
88	                    """,
89	                    new
90	                    {
91	                        id = Guid.NewGuid().ToString("D"),
92	                        email = request.Email,
93	                        issuedByUserId = adminId,
94	                        tokenHash,
95	                        issuedAt = now.ToString("o"),
96	                        expiresAt = expiresAt.ToString("o"),
97	                        consumedAt = consumedAt?.ToString("o"),
