    var rowsAffected = await _connection.ExecuteAsync(sql, new
    {
        consumedAt = consumedAt.ToString("o"),
        tokenHash,
        now = DateTimeOffset.UtcNow.ToString("o"),
    }, transaction: tx);

    return rowsAffected == 1;
}

