using System.Data;
using Kanban.Business.Interfaces;
using Kanban.Business.Transforms;
using Kanban.Contracts;
using Kanban.DataAccess.Interfaces;
using Kanban.Domain;
using Kanban.Domain.Entities;
using Kanban.Domain.Enums;
using Kanban.Domain.Events;
using Kanban.Domain.Exceptions;
using Kanban.Domain.ValueObjects;
using Microsoft.Extensions.Logging;
using Polly;
using Polly.Retry;

namespace Kanban.Business.Services;

public sealed class InvitationService : IInvitationService
{
    private readonly IUserRepository _userRepository;
    private readonly IInvitationRepository _invitationRepository;
    private readonly IAuthEventRepository _authEventRepository;
    private readonly IDbConnection _dbConnection;
    private readonly IDbConnectionFactory _transactionFactory;
    private readonly ILogger<InvitationService> _logger;

    private static readonly ResiliencePipeline RetryPolicy =
        new ResiliencePipelineBuilder()
            .AddRetry(new RetryStrategyOptions
            {
                MaxRetryAttempts = 5,
                Delay = TimeSpan.FromMilliseconds(50),
                BackoffType = DelayBackoffType.Exponential,
                UseJitter = true,
                ShouldHandle = new PredicateBuilder().Handle<Exception>(ex =>
                    ex.Message.Contains("SQLITE_BUSY", StringComparison.OrdinalIgnoreCase) ||
                    ex.Message.Contains("database is locked", StringComparison.OrdinalIgnoreCase)),
            })
            .Build();

    public InvitationService(
        IUserRepository userRepository,
        IInvitationRepository invitationRepository,
        IAuthEventRepository authEventRepository,
        IDbConnection dbConnection,
        IDbConnectionFactory transactionFactory,
        ILogger<InvitationService> logger)
    {
        Verify.That(userRepository).IsNotNull();
        Verify.That(invitationRepository).IsNotNull();
        Verify.That(authEventRepository).IsNotNull();
        Verify.That(dbConnection).IsNotNull();
        Verify.That(transactionFactory).IsNotNull();
        Verify.That(logger).IsNotNull();
        _userRepository = userRepository;
        _invitationRepository = invitationRepository;
        _authEventRepository = authEventRepository;
        _dbConnection = dbConnection;
        _transactionFactory = transactionFactory;
        _logger = logger;
    }

    public async Task<(IssueInviteResponse Response, bool IsNew)> IssueAsync(
        string email,
        Guid issuedByUserId,
        SystemRole callerRole,
        string frontendBaseUrl,
        CancellationToken cancellationToken = default)
    {
        Verify.That(email).IsNotNull().IsNotEmpty();
        Verify.That(issuedByUserId).IsNotDefault();
        Verify.That(frontendBaseUrl).IsNotNull().IsNotEmpty();

        if (callerRole != SystemRole.Admin)
            throw new ForbiddenException("invite.forbidden", "Only admins can issue invitations.");

        return await RetryPolicy.ExecuteAsync(async ct =>
        {
            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
            try
            {
                var existing = await _invitationRepository.FindActiveByEmailAsync(email, tx);
                if (existing is not null)
                {
                    var refreshToken = InvitationToken.Generate();
                    var newExpiry = DateTimeOffset.UtcNow.AddDays(7);
                    await _invitationRepository.RefreshTokenAsync(
                        existing.Id, refreshToken.Hash, newExpiry, tx);
                    tx.Commit();
                    _logger.LogInformation(
                        "Active invitation refreshed by {IssuedByUserId}", issuedByUserId);
                    return (InvitationTransforms.ToResponse(refreshToken.Raw, newExpiry, frontendBaseUrl), false);
                }

                var registeredUser = await _userRepository.FindByEmailAsync(email, tx);
                if (registeredUser is not null)
                    throw new ConflictException(
                        "invite.already_registered", "This email address is already registered.");

                var token = InvitationToken.Generate();
                var issuedAt = DateTimeOffset.UtcNow;
                var invitation = new Invitation(
                    id: Guid.NewGuid(),
                    email: email,
                    issuedByUserId: issuedByUserId,
                    tokenHash: token.Hash,
                    issuedAt: issuedAt,
                    expiresAt: issuedAt.AddDays(7),
                    consumedAt: null,
                    consumedByUserId: null);

                await _invitationRepository.InsertAsync(invitation, tx);

                var authEvent = new AuthEvent(
                    Id: Guid.NewGuid(),
                    OccurredAt: issuedAt,
                    EventType: AuthEventType.InvitationIssued,
                    UserId: issuedByUserId,
                    Outcome: "success");
                await _authEventRepository.RecordAsync(authEvent, tx);

                tx.Commit();

                _logger.LogInformation(
                    "Invitation issued by {IssuedByUserId}", issuedByUserId);

                return (InvitationTransforms.ToResponse(invitation, token.Raw, frontendBaseUrl), true);
            }
            catch
            {
                tx.Rollback();
                throw;
            }
        }, cancellationToken);
    }

    public async Task<User> AcceptAsync(
        string rawToken,
        string googleEmail,
        string googleSub,
        string displayName,
        CancellationToken cancellationToken = default)
    {
        Verify.That(rawToken).IsNotNull().IsNotEmpty();
        Verify.That(googleEmail).IsNotNull().IsNotEmpty();
        Verify.That(googleSub).IsNotNull().IsNotEmpty();
        Verify.That(displayName).IsNotNull().IsNotEmpty();

        return await RetryPolicy.ExecuteAsync(async ct =>
        {
            var tokenHash = InvitationToken.HashRaw(rawToken);
            var acceptedAt = DateTimeOffset.UtcNow;
            var newUserId = Guid.NewGuid();

            using var tx = _transactionFactory.BeginDeferredTransaction(_dbConnection);
            try
            {
                // Atomic gate: marks consumed_at — serialises concurrent accepts.
                // consumed_by_user_id is set separately below (after user is created) to avoid
                // FK constraint violations in Microsoft.Data.Sqlite 10+ which enforces them by
                // default, unlike previous versions.
                var consumed = await _invitationRepository.TryConsumeAsync(tokenHash, acceptedAt, tx);
                if (!consumed)
                    throw new NotFoundException(
                        "invite.invalid",
                        "This invitation is no longer valid. Please request a new one.");

                var invitation = await _invitationRepository.FindByTokenHashAsync(tokenHash, tx);
                if (invitation is null || !invitation.EmailMatches(googleEmail))
                    throw new BusinessRuleException(
                        "invite.email_mismatch",
                        "This invitation was issued to a different email address.");

                var user = new User(
                    id: newUserId,
                    email: invitation.Email,
                    displayName: displayName,
                    systemRole: SystemRole.Standard,
                    googleSub: googleSub,
                    registeredAt: acceptedAt,
                    lastSignInAt: null);

                await _userRepository.InsertAsync(user, tx);
                await _invitationRepository.RecordConsumerAsync(tokenHash, newUserId, tx);

                var authEvent = new AuthEvent(
                    Id: Guid.NewGuid(),
                    OccurredAt: acceptedAt,
                    EventType: AuthEventType.InvitationAccepted,
                    UserId: newUserId,
                    Outcome: "success");
                await _authEventRepository.RecordAsync(authEvent, tx);

                tx.Commit();

                _logger.LogInformation("Invitation accepted by user {UserId}", newUserId);
                return user;
            }
            catch
            {
                tx.Rollback();
                throw;
            }
        }, cancellationToken);
    }
}

using System.Security.Claims;
using FluentValidation;
using Kanban.Api.Auth;
using Microsoft.AspNetCore.Authentication;
using Kanban.Business.Interfaces;
using Kanban.Business.Transforms;
using Kanban.Contracts;
using Kanban.Domain.Enums;
using Microsoft.AspNetCore.Authentication.Cookies;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Microsoft.Extensions.Options;
using CorsOptions = Kanban.Api.Options.CorsOptions;

namespace Kanban.Api.Endpoints;

public static class InviteEndpoints
{
    public static void MapAcceptEndpoint(IEndpointRouteBuilder routes)
    {
        routes.MapPost("/invites/{token}/accept",
            async (
                string token,
                HttpContext ctx,
                IInvitationService invitationService,
                ILoggerFactory loggerFactory,
                CancellationToken ct) =>
            {
                var googleEmail = ctx.User.FindFirst("email")?.Value;
                var googleSub = ctx.User.FindFirst("sub")?.Value;
                var displayName = ctx.User.FindFirst("name")?.Value ?? googleEmail;

                if (string.IsNullOrEmpty(googleEmail) || string.IsNullOrEmpty(googleSub))
                    return Results.Unauthorized();

                var user = await invitationService.AcceptAsync(
                    token, googleEmail, googleSub, displayName!, ct);

                // AcceptAsync has committed — user is now a registered Standard user.
                // Cookie issuance is best-effort: if it fails the user can sign in via
                // the normal flow (/signin → Google → OnTicketReceived recognises them).
                try
                {
                    var identity = new ClaimsIdentity(
                        [
                            new Claim("sub", googleSub),
                            new Claim("email", user.Email),
                            new Claim("user_id", user.Id.ToString()),
                            new Claim("system_role", "standard"),
                        ],
                        CookieAuthenticationDefaults.AuthenticationScheme);
                    await ctx.SignInAsync(
                        CookieAuthenticationDefaults.AuthenticationScheme,
                        new ClaimsPrincipal(identity));
                }
                catch (Exception ex)
                {
                    loggerFactory
                        .CreateLogger(typeof(InviteEndpoints).FullName!)
                        .LogWarning(ex,
                            "Cookie issuance failed for user {UserId} after acceptance; user can sign in via normal flow",
                            user.Id);
                }

                return Results.Ok(UserTransforms.ToDto(user));
            })
            .WithName("AcceptInvite")
            .WithSummary("Accept an invitation and become a registered user")
            .Produces<CurrentUserDto>(200)
            .ProducesProblem(410)
            .ProducesProblem(422)
            .RequireAuthorization()
            .RequireRateLimiting("anonymous");
    }

    public static void Map(IEndpointRouteBuilder routes)
    {
        routes.MapPost("/invites",
            async (
                [FromBody] IssueInviteRequest request,
                IValidator<IssueInviteRequest> validator,
                IInvitationService invitationService,
                ICurrentUserService currentUser,
                IOptions<CorsOptions> corsOptions,
                CancellationToken ct) =>
            {
                var validationResult = await validator.ValidateAsync(request, ct);
                if (!validationResult.IsValid)
                {
                    var errors = validationResult.Errors
                        .GroupBy(e => e.PropertyName.ToLowerInvariant())
                        .ToDictionary(g => g.Key, g => g.Select(e => e.ErrorMessage).ToArray());
                    return Results.Problem(
                        title: "Validation failed.",
                        statusCode: StatusCodes.Status422UnprocessableEntity,
                        extensions: new Dictionary<string, object?>
                        {
                            ["code"] = "validation.failed",
                            ["errors"] = errors,
                        });
                }

                if (!currentUser.UserId.HasValue)
                    return Results.Forbid();

                var callerRole = currentUser.SystemRole == "admin"
                    ? SystemRole.Admin
                    : SystemRole.Standard;

                var frontendBaseUrl = corsOptions.Value.AllowedOrigins.FirstOrDefault()
                    ?? throw new InvalidOperationException(
                        "Cors:AllowedOrigins must contain at least one entry.");

                var (response, isNew) = await invitationService.IssueAsync(
                    request.Email,
                    currentUser.UserId.Value,
                    callerRole,
                    frontendBaseUrl,
                    ct);

                return isNew
                    ? Results.Created((string?)null, response)
                    : Results.Ok(response);
            })
            .WithName("IssueInvite")
            .WithSummary("Issue an invitation to a new user")
            .Produces<IssueInviteResponse>(201)
            .Produces<IssueInviteResponse>(200)
            .ProducesProblem(422)
            .ProducesProblem(409)
            .ProducesProblem(403)
            .RequireAuthorization("Admin")
            .RequireRateLimiting("mutating");
    }
}

import {
  FluentProvider,
  webLightTheme,
  Button,
  MessageBar,
  MessageBarBody,
  Title1,
  makeStyles,
  tokens,
} from '@fluentui/react-components'
import { useEffect, useRef } from 'react'
import { useNavigate, useParams } from 'react-router-dom'
import { useCurrentUser } from '../hooks/useCurrentUser'
import { type AcceptInviteError, useAcceptInvite } from '../hooks/useAcceptInvite'

const useStyles = makeStyles({
  root: {
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    justifyContent: 'center',
    minHeight: '100vh',
    gap: tokens.spacingVerticalL,
    textAlign: 'center',
    padding: tokens.spacingHorizontalXXL,
  },
})

export default function AcceptInvitePage() {
  const styles = useStyles()
  const { token } = useParams<{ token: string }>()
  const navigate = useNavigate()
  const { isLoading, isUnauthenticated } = useCurrentUser()
  const { mutateAsync, error } = useAcceptInvite()
  const hasAttempted = useRef(false)

  useEffect(() => {
    if (hasAttempted.current) return
    if (!isLoading && !isUnauthenticated && token) {
      hasAttempted.current = true
      mutateAsync(token)
        .then(() => navigate('/'))
        .catch(() => {})
    }
  }, [isLoading, isUnauthenticated, token, mutateAsync, navigate])

  const acceptError = error as AcceptInviteError | null

  return (
    <FluentProvider theme={webLightTheme}>
      <div className={styles.root}>
        <Title1 as="h1">Accept Invitation</Title1>

        {isUnauthenticated && (
          <Button
            as="a"
            appearance="primary"
            href={`/api/v1/auth/signin?returnUrl=${encodeURIComponent(`/accept/${token ?? ''}`)}`}
            aria-label="Accept and Sign in with Google"
          >
            Accept &amp; Sign in with Google
          </Button>
        )}

        {acceptError?.status === 410 && (
          <MessageBar intent="error" role="alert">
            <MessageBarBody>
              This invitation is no longer valid. Please request a new one.
            </MessageBarBody>
          </MessageBar>
        )}

        {acceptError?.status === 422 && (
          <MessageBar intent="error" role="alert">
            <MessageBarBody>
              This invitation was issued to a different email address.
            </MessageBarBody>
          </MessageBar>
        )}
      </div>
    </FluentProvider>
  )
}

