90	    public async Task<string> InsertInvitationWithRawTokenAsync(
91	        string email, Guid issuedByUserId,
92	        DateTimeOffset? expiresAt = null, DateTimeOffset? consumedAt = null)
93	    {
94	        _ = Server;
95	        var (rawToken, tokenHash) = GenerateRawToken();
96	        using var scope = Services.CreateScope();
97	        var db = scope.ServiceProvider.GetRequiredService<IDbConnection>();
98	        var id = Guid.NewGuid();
99	        await db.ExecuteAsync(
100	            """
101	            INSERT INTO invitations (id, email, issued_by_user_id, token_hash, issued_at, expires_at,
102	                                     consumed_at, consumed_by_user_id)
103	            VALUES (@id, @email, @issuedByUserId, @tokenHash, @issuedAt, @expiresAt, @consumedAt, NULL)
104	            """,
105	            new
106	            {
107	                id = id.ToString("D"),
108	                email,
109	                issuedByUserId = issuedByUserId.ToString("D"),
110	                tokenHash,
111	                issuedAt = DateTimeOffset.UtcNow.ToString("o"),
112	                expiresAt = (expiresAt ?? DateTimeOffset.UtcNow.AddDays(7)).ToString("o"),
113	                consumedAt = consumedAt?.ToString("o"),
114	            });
115	        return rawToken;
116	    }
117	
118	    public async Task<int> CountUsersForEmailAsync(string email)
119	    {
120	        _ = Server;
121	        using var scope = Services.CreateScope();
122	        var db = scope.ServiceProvider.GetRequiredService<IDbConnection>();
123	        return await db.QuerySingleAsync<int>(
124	            "SELECT COUNT(*) FROM users WHERE email = @email", new { email });
125	    }
126	
127	    private static (string rawToken, string tokenHash) GenerateRawToken()
128	    {
129	        var bytes = System.Security.Cryptography.RandomNumberGenerator.GetBytes(32);
130	        var raw = Convert.ToBase64String(bytes).TrimEnd('=').Replace('+', '-').Replace('/', '_');
131	        var hash = Convert.ToHexString(
132	            System.Security.Cryptography.SHA256.HashData(
133	                System.Text.Encoding.UTF8.GetBytes(raw))).ToLower();
134	        return (raw, hash);
135	    }
136	
137	    public async Task InsertActiveInvitationAsync(string email, Guid issuedByUserId)
138	    {
139	        _ = Server;
140	        using var scope = Services.CreateScope();
141	        var db = scope.ServiceProvider.GetRequiredService<IDbConnection>();
142	        var id = Guid.NewGuid();
143	        var tokenHash = Convert.ToHexString(
144	            System.Security.Cryptography.SHA256.HashData(
145	                System.Security.Cryptography.RandomNumberGenerator.GetBytes(32)));
146	        await db.ExecuteAsync(
147	            """
148	            INSERT INTO invitations (id, email, issued_by_user_id, token_hash, issued_at, expires_at,
149	                                     consumed_at, consumed_by_user_id)
150	            VALUES (@id, @email, @issuedByUserId, @tokenHash, @issuedAt, @expiresAt, NULL, NULL)
151	            """,
152	            new
153	            {
154	                id = id.ToString("D"),
155	                email,
156	                issuedByUserId = issuedByUserId.ToString("D"),
157	                tokenHash,
158	                issuedAt = DateTimeOffset.UtcNow.ToString("o"),
159	                expiresAt = DateTimeOffset.UtcNow.AddDays(7).ToString("o"),
160	            });
161	    }
