163	    public async Task<Guid> GetSeededAdminIdAsync()
164	    {
165	        _ = Server; // ensure app startup (and DbUp migrations) have run before querying
166	        using var scope = Services.CreateScope();
167	        var db = scope.ServiceProvider.GetRequiredService<IDbConnection>();
168	        return await db.QuerySingleAsync<Guid>(
169	            "SELECT id FROM users WHERE email = @email",
170	            new { email = AdminEmail });
